{"content":""""Summarize log severities over date ranges.

Reads the reference date from reference_date.txt, scans ./logs/*.log
(filenames YYYY-MM-DD_<source>.log), and writes ./summary.csv with counts
of ERROR / WARNING / INFO for today, last_7_days, last_30_days,
month_to_date and total.
"""

import csv
import re
from datetime import date, timedelta
from pathlib import Path

SEVERITIES = ["ERROR", "WARNING", "INFO"]
PERIODS = ["today", "last_7_days", "last_30_days", "month_to_date", "total"]
FILENAME_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})_.+\.log$")

BASE = Path(__file__).resolve().parent
LOGS_DIR = BASE / "logs"
REFERENCE_FILE = BASE / "reference_date.txt"
OUTPUT_FILE = BASE / "summary.csv"


def read_reference_date() -> date:
    text = REFERENCE_FILE.read_text(encoding="utf-8").strip()
    return date.fromisoformat(text)


def iter_log_files():
    for path in sorted(LOGS_DIR.glob("*.log")):
        m = FILENAME_RE.match(path.name)
        if not m:
            continue
        yield date.fromisoformat(m.group(1)), path


def count_severities(path: Path) -> dict:
    counts = {s: 0 for s in SEVERITIES}
    with path.open("r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            for sev in SEVERITIES:
                if sev in line:
                    counts[sev] += 1
                    break
    return counts


def main() -> None:
    ref = read_reference_date()
    start_7 = ref - timedelta(days=6)
    start_30 = ref - timedelta(days=29)
    start_month = ref.replace(day=1)

    totals = {p: {s: 0 for s in SEVERITIES} for p in PERIODS}

    for log_date, path in iter_log_files():
        counts = count_severities(path)
        for sev in SEVERITIES:
            n = counts[sev]
            if n == 0:
                continue
            totals["total"][sev] += n
            if log_date == ref:
                totals["today"][sev] += n
            if start_7 <= log_date <= ref:
                totals["last_7_days"][sev] += n
            if start_30 <= log_date <= ref:
                totals["last_30_days"][sev] += n
            if start_month <= log_date <= ref:
                totals["month_to_date"][sev] += n

    with OUTPUT_FILE.open("w", encoding="utf-8", newline="") as fh:
        writer = csv.writer(fh)
        writer.writerow(["period", "severity", "count"])
        for period in PERIODS:
            for sev in SEVERITIES:
                writer.writerow([period, sev, totals[period][sev]])

    print(f"reference date: {ref}")
    print(f"wrote {OUTPUT_FILE}")


if __name__ == "__main__":
    main()
